import static java.lang.Integer.parseInt;
import static java.nio.charset.StandardCharsets.UTF_8;
import static java.nio.file.Files.readString;

import java.io.IOException;
import java.net.Socket;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Comparator;

public class SetupMinio {

    static final String MINIO_EXE_PATH = fromEnv("MINIO_EXE", "../minio/minio");
    static final String PID_PATH = fromEnv("MINIO_PID", "../minio/minio.pid");
    static final String MC_EXE_PATH = fromEnv("MC_EXE", "../minio/mc");
    static final String DATA_PATH = fromEnv("MINIO_DATA", "./build/data1");
    static final String MINIO_HOST = fromEnv("MINIO_HOST", "127.0.0.1");
    static final String MINIO_PORT = fromEnv("MINIO_PORT", "9000");

    public static void main(String[] args) throws Exception {
        killMinioServer();
        deleteMinioData();
        setupMinio();
    }

    static void killMinioServer() throws Exception {
        Path pidPath = Paths.get(PID_PATH);
        if (!Files.exists(pidPath)) {
            return;
        }
        long pid = Long.parseLong(readString(pidPath, UTF_8));
        System.out.println("Killing Minio server process, pid: " + pid + " ...");
        new ProcessBuilder("/usr/bin/kill", String.valueOf(pid)).inheritIO().start().waitFor();
        Files.delete(pidPath);
    }

    static void deleteMinioData() throws Exception {
        Path minioDataPath = Paths.get(DATA_PATH);
        if (!Files.exists(minioDataPath)) {
            return;
        }
        System.out.println("Deleting Minio data: " + minioDataPath + " ...");
        Files.walk(minioDataPath).sorted(Comparator.reverseOrder()).forEach(p -> {
            try {
                Files.delete(p);
            } catch (IOException e) {
                throw new RuntimeException("Failed to delete " + p, e);
            }
        });
    }

    static void setupMinio() throws Exception {
        System.out.println("Starting Minio server ...");
        Process minioServerProcess =
            new ProcessBuilder(MINIO_EXE_PATH, "server", "--address", MINIO_HOST + ":" + MINIO_PORT, DATA_PATH)
                .inheritIO()
                .start();
        Files.write(Paths.get(PID_PATH), String.valueOf(minioServerProcess.pid()).getBytes(UTF_8));
        boolean minioServerStarted = false;
        for (int i = 0; i < 16; i++) {
            try (Socket sock = new Socket(MINIO_HOST, parseInt(MINIO_PORT))) {
                minioServerStarted = true;
                break;
            } catch (IOException e) {
                Thread.sleep(1000);
            }
        }
        if (!minioServerStarted) {
            throw new RuntimeException("Cannot start Minio");
        }
        Thread.sleep(2000); // improve log output
        System.out.println("Minio server started, pid: " + minioServerProcess.pid() + ", creating bucket ...");
        int mcAliasStatus = new ProcessBuilder(MC_EXE_PATH, "alias", "set", "local",
                                               "http://" + MINIO_HOST + ":" + MINIO_PORT, "minioadmin", "minioadmin")
                                .inheritIO()
                                .start()
                                .waitFor();
        if (mcAliasStatus != 0) {
            killMinioServer();
            throw new RuntimeException("Minio mc alias set error, status: " + mcAliasStatus);
        }
        int mcMbStatus = new ProcessBuilder(MC_EXE_PATH, "mb", "local/bucket1").inheritIO().start().waitFor();
        if (mcMbStatus != 0) {
            killMinioServer();
            throw new RuntimeException("Minio mc mb error, status: " + mcAliasStatus);
        }
        System.out.println("Minio server set up successfully");
    }

    static String fromEnv(String envVarName, String defaultValue) {
        String env = System.getenv(envVarName);
        if (null != env) {
            return env;
        }
        return defaultValue;
    }
}

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

class SetupDuckLake {

    static final String POSTGRES_HOST = fromEnv("POSTGRES_HOST", "127.0.0.1");
    static final String POSTGRES_PORT = fromEnv("POSTGRES_PORT", "5432");
    static final String POSTGRES_MAINTENANCE_DB = fromEnv("POSTGRES_MAINTENANCE_DB", "postgres");
    static final String POSTGRES_USERNAME = fromEnv("POSTGRES_USERNAME", "postgres");
    static final String POSTGRES_PASSWORD = fromEnv("POSTGRES_PASSWORD", "postgres");
    static final String POSTGRES_URL = fromEnv("POSTGRES_URL", "jdbc:postgresql://" + POSTGRES_HOST + ":" +
                                                                   POSTGRES_PORT + "/" + POSTGRES_MAINTENANCE_DB);
    static final String DUCKLAKE_CATALOG_DB = fromEnv("DUCKLAKE_CATALOG_DB_NAME", "lake_test");
    static final String DUCKLAKE_URL =
        fromEnv("DUCKLAKE_URL", "ducklake:postgres:postgresql://" + POSTGRES_USERNAME + ":" + POSTGRES_PASSWORD + "@" +
                                    POSTGRES_HOST + ":" + POSTGRES_PORT + "/" + DUCKLAKE_CATALOG_DB);
    static final String PARQUET_FILE_URL =
        fromEnv("DUCKLAKE_DATA_PATH", "https://blobs.duckdb.org/data/taxi_2019_04.parquet");
    static final String SESSION_INIT_SQL_FILE =
        fromEnv("SESSION_INIT_SQL_FILE", "./src/test/external/spark-session-init.sql");

    public static void main(String[] args) throws Exception {
        setupPostgres();
        setupDuckLake();
        System.out.println("Success");
    }

    static void setupPostgres() throws Exception {
        System.out.println("Creating Postgres database ...");
        try (Connection conn = DriverManager.getConnection(POSTGRES_URL, POSTGRES_USERNAME, POSTGRES_PASSWORD);
             Statement stmt = conn.createStatement()) {
            stmt.execute("DROP DATABASE IF EXISTS " + DUCKLAKE_CATALOG_DB);
            stmt.execute("CREATE DATABASE " + DUCKLAKE_CATALOG_DB);
        }
    }

    static void setupDuckLake() throws Exception {
        System.out.println("Creating DuckLake instance ...");
        try (Connection conn =
                 DriverManager.getConnection("jdbc:duckdb:;session_init_sql_file=" + SESSION_INIT_SQL_FILE + ";");
             Statement stmt = conn.createStatement()) {
            stmt.execute("ATTACH '" + DUCKLAKE_URL + "' AS lake (DATA_PATH 's3://bucket1')");
            stmt.execute("USE lake");
            System.out.println("Loading data from URL: '" + PARQUET_FILE_URL + "' ...");
            stmt.execute("CREATE TABLE tab1 AS FROM '" + PARQUET_FILE_URL + "'");
        }
        try (Connection conn = DriverManager.getConnection("jdbc:duckdb:" + DUCKLAKE_URL +
                                                           ";session_init_sql_file=" + SESSION_INIT_SQL_FILE + ";");
             Statement stmt = conn.createStatement()) {
            try (ResultSet rs = stmt.executeQuery("SELECT count(*) FROM tab1")) {
                rs.next();
                System.out.println("Records loaded: " + rs.getLong(1));
            }
        }
    }

    static String fromEnv(String envVarName, String defaultValue) {
        String env = System.getenv(envVarName);
        if (null != env) {
            return env;
        }
        return defaultValue;
    }
}

#include "duckdb/main/capi/cast/from_decimal.hpp"
#include "duckdb/common/types/decimal.hpp"

namespace duckdb {

//! DECIMAL -> VARCHAR
template <>
bool CastDecimalCInternal(duckdb_result *source, duckdb_string &result, idx_t col, idx_t row) {
	auto result_data = (duckdb::DuckDBResultData *)source->internal_data;
	auto &query_result = result_data->result;
	auto &source_type = query_result->GetTypes()[col];
	auto width = duckdb::DecimalType::GetWidth(source_type);
	auto scale = duckdb::DecimalType::GetScale(source_type);
	StringHeap heap;
	duckdb::string_t result_string;
	auto source_value = UnsafeFetch<hugeint_t>(source, col, row);
	switch (source_type.InternalType()) {
	case duckdb::PhysicalType::INT16:
		result_string =
		    duckdb::StringCastFromDecimal::Operation<int16_t>(static_cast<int16_t>(source_value), width, scale, heap);
		break;
	case duckdb::PhysicalType::INT32:
		result_string =
		    duckdb::StringCastFromDecimal::Operation<int32_t>(static_cast<int32_t>(source_value), width, scale, heap);
		break;
	case duckdb::PhysicalType::INT64:
		result_string =
		    duckdb::StringCastFromDecimal::Operation<int64_t>(static_cast<int64_t>(source_value), width, scale, heap);
		break;
	case duckdb::PhysicalType::INT128:
		result_string = duckdb::StringCastFromDecimal::Operation<hugeint_t>(source_value, width, scale, heap);
		break;
	default:
		throw duckdb::InternalException("Unimplemented internal type for decimal");
	}
	result.data = reinterpret_cast<char *>(duckdb_malloc(sizeof(char) * (result_string.GetSize() + 1)));
	if (!result.data) {
		return false;
	}
	memcpy(result.data, result_string.GetData(), result_string.GetSize());
	result.data[result_string.GetSize()] = '\0';
	result.size = result_string.GetSize();
	return true;
}

template <class INTERNAL_TYPE>
duckdb_hugeint FetchInternals(void *source_address) {
	throw duckdb::NotImplementedException("FetchInternals not implemented for internal type");
}

template <>
duckdb_hugeint FetchInternals<int16_t>(void *source_address) {
	const int16_t source_value = static_cast<int16_t>(UnsafeFetchFromPtr<int64_t>(source_address));
	duckdb_hugeint result;
	int16_t intermediate_result;

	if (!TryCast::Operation<int16_t, int16_t>(source_value, intermediate_result)) {
		intermediate_result = FetchDefaultValue::Operation<int16_t>();
	}
	hugeint_t hugeint_result = Hugeint::Cast<int16_t>(intermediate_result);
	result.lower = hugeint_result.lower;
	result.upper = hugeint_result.upper;
	return result;
}
template <>
duckdb_hugeint FetchInternals<int32_t>(void *source_address) {
	const int32_t source_value = static_cast<int32_t>(UnsafeFetchFromPtr<int64_t>(source_address));
	duckdb_hugeint result;
	int32_t intermediate_result;

	if (!TryCast::Operation<int32_t, int32_t>(source_value, intermediate_result)) {
		intermediate_result = FetchDefaultValue::Operation<int32_t>();
	}
	hugeint_t hugeint_result = Hugeint::Cast<int32_t>(intermediate_result);
	result.lower = hugeint_result.lower;
	result.upper = hugeint_result.upper;
	return result;
}
template <>
duckdb_hugeint FetchInternals<int64_t>(void *source_address) {
	const int64_t source_value = UnsafeFetchFromPtr<int64_t>(source_address);
	duckdb_hugeint result;
	int64_t intermediate_result;

	if (!TryCast::Operation<int64_t, int64_t>(source_value, intermediate_result)) {
		intermediate_result = FetchDefaultValue::Operation<int64_t>();
	}
	hugeint_t hugeint_result = Hugeint::Cast<int64_t>(intermediate_result);
	result.lower = hugeint_result.lower;
	result.upper = hugeint_result.upper;
	return result;
}
template <>
duckdb_hugeint FetchInternals<hugeint_t>(void *source_address) {
	const hugeint_t source_value = UnsafeFetchFromPtr<hugeint_t>(source_address);
	duckdb_hugeint result;
	hugeint_t intermediate_result;

	if (!TryCast::Operation<hugeint_t, hugeint_t>(source_value, intermediate_result)) {
		intermediate_result = FetchDefaultValue::Operation<hugeint_t>();
	}
	result.lower = intermediate_result.lower;
	result.upper = intermediate_result.upper;
	return result;
}

//! DECIMAL -> DECIMAL (internal fetch)
template <>
bool CastDecimalCInternal(duckdb_result *source, duckdb_decimal &result, idx_t col, idx_t row) {
	auto result_data = (duckdb::DuckDBResultData *)source->internal_data;
	result_data->result->GetTypes()[col].GetDecimalProperties(result.width, result.scale);
	auto source_address = UnsafeFetchPtr<hugeint_t>(source, col, row);

	if (result.width > duckdb::Decimal::MAX_WIDTH_INT64) {
		result.value = FetchInternals<hugeint_t>(source_address);
	} else if (result.width > duckdb::Decimal::MAX_WIDTH_INT32) {
		result.value = FetchInternals<int64_t>(source_address);
	} else if (result.width > duckdb::Decimal::MAX_WIDTH_INT16) {
		result.value = FetchInternals<int32_t>(source_address);
	} else {
		result.value = FetchInternals<int16_t>(source_address);
	}
	return true;
}

} // namespace duckdb

